(()=>{
 const panel=document.querySelector('#leads-panel');
 const escape=value=>String(value??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
 const phone=number=>number==='554733180795'?'(47) 3318-0795':number==='5547988237774'?'(47) 98823-7774':'(47) 99619-0693';
 const sources={cabecalho:'Cabeçalho',rodape:'Rodapé',flutuante:'Botão flutuante',veiculo:'Tenho interesse',contato:'Página de contato',outro:'Outros botões'};
 const count=value=>new Intl.NumberFormat('pt-BR').format(value);
 const date=value=>new Intl.DateTimeFormat('pt-BR',{timeZone:'America/Sao_Paulo',dateStyle:'short',timeStyle:'short'}).format(new Date(value));
 let query='period=30',sequence=0;
 panel.innerHTML=`<div class="leads-heading"><div><span class="eyebrow brand">ATENDIMENTO EM NÚMEROS</span><h2>Do interesse à conversa.</h2><p>Acompanhe os cliques que abriram o WhatsApp e como foram distribuídos entre os três números.</p></div><button class="button outline small" id="leads-refresh">Atualizar ↻</button></div><div class="leads-filters"><div class="leads-presets" aria-label="Período do relatório"><button data-period="1">Hoje</button><button data-period="7">7 dias</button><button data-period="30" class="selected">30 dias</button><button data-period="all">Todo o período</button></div><form id="leads-range"><label>De<input type="date" name="from" aria-label="Data inicial"></label><label>Até<input type="date" name="to" aria-label="Data final"></label><button class="button outline small">Aplicar período</button></form></div><p id="leads-error" role="alert"></p><div id="leads-results" aria-live="polite"></div>`;
 async function load(){
  const ticket=++sequence,button=panel.querySelector('#leads-refresh');button.disabled=true;panel.querySelector('#leads-error').textContent='';
  try{
   const data=await api('admin/leads?'+query);if(ticket!==sequence)return;
   const form=panel.querySelector('#leads-range');form.elements.from.value=data.range.from||'';form.elements.to.value=data.range.to||'';
   panel.querySelector('#leads-results').innerHTML=`<div class="leads-summary"><article><span>CLIQUES NO PERÍODO</span><strong>${count(data.total)}</strong><small>Aberturas do WhatsApp</small></article><article><span>NÚMEROS ACIONADOS</span><strong>${data.byNumber.filter(r=>r.count>0).length}<small> / 3</small></strong><small>Distribuição do atendimento</small></article><article><span>VEÍCULOS COM INTERESSE</span><strong>${count(data.vehicleCount)}</strong><small>Carros associados aos cliques</small></article></div><div class="leads-number-grid">${data.byNumber.map(r=>{const percent=data.total?Math.round(r.count/data.total*100):0;return `<article class="leads-number"><span class="eyebrow brand">WHATSAPP</span><h3>${phone(r.number)}</h3><div><strong>${count(r.count)}</strong><span>cliques · ${percent}% do total</span></div><progress value="${r.count}" max="${Math.max(data.total,1)}" aria-label="Participação do número ${phone(r.number)}"></progress></article>`}).join('')}</div>${!data.total?'<p class="leads-empty">Nenhum clique registrado neste período. Os próximos atendimentos pelo site aparecerão aqui.</p>':''}<div class="leads-breakdown"><section class="leads-card"><h3>Onde o interesse começou</h3>${data.byPlacement.length?data.byPlacement.map(r=>`<div class="leads-rank"><span>${escape(sources[r.placement]||'Outros botões')}</span><strong>${count(r.count)}</strong></div>`).join(''):'<p>As origens dos cliques aparecerão após os primeiros acessos ao WhatsApp.</p>'}</section><section class="leads-card"><h3>Veículos mais procurados</h3>${data.byVehicle.length?data.byVehicle.map(r=>`<div class="leads-rank"><span>${escape(r.label||r.id)}</span><strong>${count(r.count)}</strong></div>`).join(''):'<p>Cliques feitos nas páginas dos veículos serão associados ao respectivo carro.</p>'}</section></div><section class="leads-card"><h3>Últimos cliques do período</h3><p>Até 50 registros mais recentes. Horário de Brasília.</p>${data.recent.length?`<div class="leads-table-wrap" role="region" aria-label="Últimos cliques de WhatsApp" tabindex="0"><table class="leads-table"><thead><tr><th>Data e hora</th><th>WhatsApp de destino</th><th>Botão</th><th>Veículo / página</th></tr></thead><tbody>${data.recent.map(r=>`<tr><td>${escape(date(r.createdAt))}</td><td>${phone(r.number)}</td><td>${escape(sources[r.placement]||'Outros botões')}</td><td>${escape(r.vehicleLabel||r.vehicleId||r.page)}</td></tr>`).join('')}</tbody></table></div>`:'<p>Nenhum registro para exibir.</p>'}</section><p class="leads-footnote">Esta contagem representa cliques para abrir o WhatsApp. Não confirma o envio de mensagens nem representa pessoas únicas. O histórico começa com a ativação desta funcionalidade.${data.trackingSince?' Primeiro registro: '+escape(date(data.trackingSince))+'.':''}</p>`;
  }catch(error){if(ticket===sequence)panel.querySelector('#leads-error').textContent=error.message}finally{if(ticket===sequence)button.disabled=false}
 }
 panel.querySelector('#leads-refresh').onclick=load;
 panel.querySelectorAll('[data-period]').forEach(button=>button.onclick=()=>{query='period='+button.dataset.period;panel.querySelectorAll('[data-period]').forEach(b=>b.classList.toggle('selected',b===button));load()});
 panel.querySelector('#leads-range').onsubmit=event=>{event.preventDefault();const data=new FormData(event.target),params=new URLSearchParams();if(data.get('from'))params.set('from',data.get('from'));if(data.get('to'))params.set('to',data.get('to'));query=params.size?params.toString():'period=all';panel.querySelectorAll('[data-period]').forEach(b=>b.classList.remove('selected'));load()};
 window.gasparLeads={open:load};
})();
